const prep = $('00 Prepare Input').item.json;
if (prep.__invalid) { return [{ json: { status:'failed', response: prep.response, verificationStatus:'Failed' } }]; }
const item = items[0];
const err = httpError(item);
if (err) { return [{ json: { status: 'failed', response: 'Tool failed: Yes\n' + 'Tool used: WF_LIST_EMAIL_ATTACHMENTS\n' + 'Error message: ' + (err) + '\n' + 'Action taken: None\n' + 'Verification status: Failed', verificationStatus: 'Failed' } }]; }
const rows = Array.isArray((item.json||{}).value) ? item.json.value : [];
const real = rows.filter(a => !a.isInline);
if (real.length === 0) {
  return [{ json: { status:'ok', count:0, response:'This email has no (non-inline) attachments.\nVerification status: Passed', verificationStatus:'Passed' } }];
}
const list = real.map((a, i) => ({ index:i+1, attachment_id:a.id, name:a.name, contentType:a.contentType, size:a.size, isInline:!!a.isInline }));
const lines = list.map(a => `${a.index}. ${a.name} (${a.contentType||'unknown'}, ${a.size||0} bytes)`);
